from pathlib import Path
root=Path('frontend')
T=root/'templates'
P=T/'partials'
CSS=root/'static'/'css'
JS=root/'static'/'js'
for d in [T,P,CSS,JS]: d.mkdir(parents=True, exist_ok=True)

def w(path, text):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(text.strip()+"\n", encoding='utf-8')

