# --- base files ---
w(T/'base.html', r'''
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover"><meta name="theme-color" content="#7c3aed"><meta name="color-scheme" content="light dark"><link rel="manifest" href="/manifest.json"><title>{% block title %}SocialHub{% endblock %}</title><script>(function(){try{var p=localStorage.getItem('socialhub-theme')||'system';var m=matchMedia('(prefers-color-scheme: dark)');var t=p==='system'?(m.matches?'dark':'light'):p;document.documentElement.dataset.theme=t;document.documentElement.dataset.themePreference=p;document.documentElement.style.colorScheme=t}catch(e){document.documentElement.dataset.theme='light'}})();</script><link rel="preconnect" href="https://cdnjs.cloudflare.com"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="/static/css/style.css">{% block page_styles %}{% endblock %}{% block styles %}{% endblock %}</head><body data-page="{% block page_class %}{{ request.url.path.strip('/').replace('/', '-') or 'home' }}{% endblock %}" class="{% block body_class %}{% endblock %}"><a class="skip-link" href="#main-content">Skip to content</a><div class="app-shell">{% include 'partials/desktop_sidebar.html' %}<div class="app-main">{% include 'partials/topbar.html' %}<main id="main-content" class="page-container page-enter" tabindex="-1">{% block content %}{% endblock %}</main></div>{% include 'partials/right_sidebar.html' %}{% include 'partials/mobile_bottom_nav.html' %}</div>{% include 'partials/user_menu.html' %}{% include 'partials/notification_menu.html' %}{% include 'partials/create_post_modal.html' %}{% include 'partials/create_reel_modal.html' %}{% include 'partials/create_story_modal.html' %}{% include 'partials/share_modal.html' %}{% include 'partials/comments_drawer.html' %}{% include 'partials/confirmation_modal.html' %}{% include 'partials/loading_overlay.html' %}{% include 'partials/toast_container.html' %}<script src="/static/js/app.js" defer></script><script src="/static/js/ui-refresh.js" defer></script>{% block page_scripts %}{% endblock %}{% block scripts %}{% endblock %}</body></html>''')
w(T/'auth_base.html', r'''
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover"><meta name="theme-color" content="#7c3aed"><title>{% block title %}SocialHub Auth{% endblock %}</title><script>(function(){try{var p=localStorage.getItem('socialhub-theme')||'system';var m=matchMedia('(prefers-color-scheme: dark)');var t=p==='system'?(m.matches?'dark':'light'):p;document.documentElement.dataset.theme=t;document.documentElement.dataset.themePreference=p;document.documentElement.style.colorScheme=t}catch(e){document.documentElement.dataset.theme='light'}})();</script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="/static/css/style.css"></head><body data-page="{% block page_name %}auth{% endblock %}" class="auth-body"><main class="auth-shell page-enter"><section class="auth-art"><a class="brand" href="/"><span class="brand-mark"><i class="fas fa-bolt"></i></span><span>SocialHub</span></a><h1>Connect, create, and grow.</h1><p>Secure access to your SocialHub community, creator tools, analytics, live rooms, and wallet.</p><button class="theme-toggle btn btn-ghost" type="button"><i class="fas fa-moon"></i> Theme</button></section><section class="auth-panel">{% block content %}{% endblock %}</section></main>{% include 'partials/toast_container.html' %}<script src="/static/js/app.js" defer></script><script src="/static/js/ui-refresh.js" defer></script>{% block scripts %}{% endblock %}</body></html>''')

